import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['postoperative PTH thyroidectomy discharge length of stay','PTH guided discharge thyroidectomy randomized','early PTH thyroidectomy hospital stay hypocalcemia']
for term in terms:
 r=requests.get(u,params={'db':'pubmed','term':term,'retmax':8,'retmode':'json'},timeout=20)
 print('\nQUERY',term,'STATUS',r.status_code)
 ids=r.json().get('esearchresult',{}).get('idlist',[])
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids:
   d=x[i]; print(i,d.get('pubdate'),d.get('title'))
 else: print('No results')
